fn_guiscr_reset:		; sub reset (asm keyword), GuiScr.cls line 87
            ld (var_guiscr_hsp), sp              ; (the real stack for the calls: SP is the thread) [88]
            ld sp, (ntc_csp)		; GuiScr.cls 89
            ld hl, #E000                ; the hash table, the tiles' copies, the full flag (#EC00) [90]
            ld de, #E001		; GuiScr.cls 91
            ld bc, #0C00		; GuiScr.cls 92
            ld (hl), 0		; GuiScr.cls 93
            ldir		; GuiScr.cls 94
            ld a, 1		; GuiScr.cls 95
            ld (gz_nt), a		; GuiScr.cls 96
            ld hl, #8000		; GuiScr.cls 97
            ld de, #8001		; GuiScr.cls 98
            ld bc, #3FFF		; GuiScr.cls 99
            ld (hl), 0		; GuiScr.cls 100
            ldir		; GuiScr.cls 101
            call gz_map		; GuiScr.cls 102
            ld hl, #C000                ; the tilemap (80 x 32) and tile 0 blank [103]
            ld de, #C001		; GuiScr.cls 104
            ld bc, 80 * 32 - 1		; GuiScr.cls 105
            ld (hl), 0		; GuiScr.cls 106
            ldir		; GuiScr.cls 107
            ld hl, #CA00		; GuiScr.cls 108
            ld b, 8		; GuiScr.cls 109
fn_guiscr_reset_gz_r0:      ld (hl), 0		; GuiScr.cls 110
            inc hl		; GuiScr.cls 111
            djnz fn_guiscr_reset_gz_r0		; GuiScr.cls 112
            call gz_unmap		; GuiScr.cls 113
